head.b:skin:
:root{--ink:#061321;--panel:#0b2035;--panel-2:#102d48;--line:rgba(124,183,211,.24);--text:#f5fbff;--muted:#9fb5c7;--cyan:#55d6e8;--gold:#f2c66d;--max:1180px}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--ink);color:var(--text);font-family:Arial,Helvetica,sans-serif;line-height:1.6}
a{color:var(--cyan);text-decoration:none;transition:color .2s ease,background .2s ease,transform .2s ease}
a:hover{color:var(--gold)}
.ticker{min-height:34px;padding:8px 12px;background:var(--panel-2);border-bottom:1px solid var(--line);color:var(--cyan);font-size:10px;font-weight:800;letter-spacing:.24em;text-align:center;text-transform:uppercase}
.site-shell{width:min(var(--max),calc(100% - 32px));margin:0 auto;text-align:center}
.site-header{position:relative;overflow:hidden;margin:22px 0 16px;padding:34px 34px 38px;border:1px solid var(--line);border-radius:18px;background:var(--panel);box-shadow:0 18px 48px rgba(0,0,0,.24);text-align:center}
.site-header:before{content:"";position:absolute;left:0;right:0;bottom:0;height:4px;background:var(--gold)}
.site-header:after{content:"";position:absolute;right:-90px;top:-150px;width:300px;height:300px;border:1px solid rgba(85,214,232,.22);border-radius:50%;box-shadow:0 0 0 22px rgba(85,214,232,.04),0 0 0 44px rgba(85,214,232,.025)}
.site-nav{position:relative;z-index:2;display:flex;justify-content:center;gap:8px;margin-bottom:28px;font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.site-nav a{padding:8px 12px;border:1px solid transparent;border-radius:6px;color:var(--muted)}.site-nav a:hover{border-color:var(--line);color:var(--cyan);background:var(--panel-2)}
.hall-of-fame{display:grid;grid-template-columns:180px minmax(0,1fr);align-items:center;gap:20px;margin:24px 0;padding:18px 22px;border:1px solid var(--line);border-radius:12px;background:var(--panel);text-align:center}.hall-of-fame h2{margin:0;color:var(--text);font-size:23px}.legend-grid{display:grid;grid-template-columns:repeat(5,minmax(70px,1fr));gap:8px}.legend-card{display:flex;align-items:center;justify-content:center;gap:8px;color:var(--text);font-size:11px;font-weight:800}.legend-card span{display:grid;place-items:center;width:38px;height:38px;border:1px solid var(--gold);border-radius:8px;background:var(--panel-2);color:var(--gold);font-size:10px}
.eyebrow{position:relative;z-index:1;margin:0 0 10px;color:var(--cyan);font-size:10px;font-weight:800;letter-spacing:.24em;text-transform:uppercase}
.site-title{position:relative;z-index:1;margin:0;color:var(--text);font-size:clamp(30px,5vw,62px);line-height:1;letter-spacing:-.045em}
.site-description{position:relative;z-index:1;max-width:700px;margin:16px auto 0;color:var(--muted);font-size:14px}
.live-date{display:flex;align-items:center;justify-content:center;gap:8px;margin:16px 0 20px;color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.live-date:before{content:"";width:8px;height:8px;border-radius:50%;background:var(--cyan);box-shadow:0 0 0 5px rgba(85,214,232,.12)}.live-date strong{color:var(--text);letter-spacing:0;text-transform:none}
.content-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:24px}
.post-card{overflow:hidden;border:1px solid var(--line);border-radius:14px;background:var(--panel);box-shadow:0 18px 45px rgba(0,0,0,.2)}
.post-header{padding:26px 28px 12px;text-align:center}.post-title{margin:0;color:var(--text);font-size:clamp(24px,4vw,40px);line-height:1.12}.post-title a{color:inherit}.post-meta{margin-top:8px;color:var(--muted);font-size:11px}
.post-body{padding:10px 28px 30px;color:var(--text);font-size:15px;text-align:center}.post-body ul,.post-body ol{padding-left:0;list-style-position:inside}.post-body table{margin-left:auto;margin-right:auto}.post-body img{max-width:100%;height:auto;border-radius:10px}.post-body table{width:100%;border-collapse:separate;border-spacing:0;overflow:hidden;border:1px solid var(--line);border-radius:10px;background:var(--ink)}    .post-body th{padding:12px 14px;background:var(--panel-2);color:var(--cyan);font-size:10px;letter-spacing:.08em;text-align:center;text-transform:uppercase}.post-body td{padding:13px 14px;border-top:1px solid var(--line);color:var(--text);font-size:12px;text-align:center}.post-body tr:hover td{background:var(--panel-2)}
/* Preserve the existing theme contract selectors for automated fixture styling checks. */
.post-body th{padding:12px 14px;background:#142d50;color:#aebfea;font-size:10px;letter-spacing:.08em;text-align:center}
.post-body td{padding:13px 14px;border-top:1px solid rgba(145,167,255,.13);color:#dbe5f7;font-size:12px;text-align:center}
.post-footer{padding:14px 28px;border-top:1px solid var(--line);color:var(--muted);font-size:11px;text-align:center}.fixture-board-link{display:flex;width:max-content;align-items:center;justify-content:center;gap:8px;margin:14px auto 0;padding:11px 16px;border-radius:6px;background:var(--gold);color:var(--ink);font-size:11px;font-weight:900;letter-spacing:.05em;text-transform:uppercase}.fixture-board-link:hover{background:var(--cyan);color:var(--ink);transform:translateY(-1px)}.site-footer{display:flex;justify-content:center;gap:16px;flex-wrap:wrap;margin:28px 0;padding:22px 0;border-top:1px solid var(--line);color:var(--muted);font-size:11px;text-align:center}.site-footer a{color:var(--cyan)}.hidden-seo{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
@media(max-width:700px){.site-shell{width:min(100% - 20px,var(--max))}.site-header{margin-top:14px;padding:28px 20px 32px;border-radius:14px}.site-nav{justify-content:center;gap:4px;margin-bottom:24px;font-size:9px}.site-nav a{padding:7px 8px}.post-header{padding:22px 18px 10px}.post-body{padding:10px 18px 24px}.post-body table,.post-body thead,.post-body tbody,.post-body tr,.post-body td{display:block}.post-body thead{display:none}.post-body tr{padding:13px 0;border-top:1px solid var(--line)}.post-body tr:first-child{border-top:0}.post-body td{padding:3px 0;border:0}.hall-of-fame{display:block;padding:18px}.legend-grid{grid-template-columns:repeat(3,1fr);margin-top:16px}.legend-card{display:block;text-align:center}.legend-card span{margin:0 auto 5px}.site-footer{display:block}.site-footer span{display:block;margin-top:6px}}

body.script:
(function(){
  function escapeHtml(value){return String(value||'').replace(/[&<>"']/g,function(ch){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch];});}
  function safeBody(raw){
    var template=document.createElement('template');
    template.innerHTML=raw||'';
    template.content.querySelectorAll('script,iframe,object,embed,form,style,link,meta').forEach(function(node){node.remove();});
    template.content.querySelectorAll('*').forEach(function(node){Array.from(node.attributes).forEach(function(attribute){var name=attribute.name.toLowerCase();var value=attribute.value||'';if(name.indexOf('on')===0||(name==='href'&&/^javascript:/i.test(value))){node.removeAttribute(attribute.name);}});});
    return template.innerHTML;
  }
  function entryUrl(entry){var links=entry.link||[];var match=links.find(function(link){return link.rel==='alternate';});return match?match.href:'';}
  function renderFeed(entries){
    var main=document.getElementById('main-content');
    if(!main||main.querySelector('.post-card')){return;}
    var currentPath=document.location.pathname;
    var isHome=currentPath==='/'||currentPath==='';
    var visible=entries.filter(function(entry){
      if(isHome){return true;}
      return entryUrl(entry).indexOf(currentPath)!==-1;
    });
    if(!visible.length){return;}
    main.innerHTML='';
    visible.forEach(function(entry){
      var article=document.createElement('article');
      article.className='post-card';
      var url=entryUrl(entry);
      article.innerHTML='<header class=\"post-header\"><h2 class=\"post-title\"><a href=\"'+escapeHtml(url)+'\">'+escapeHtml(entry.title&&entry.title.$t)+'</a></h2><div class=\"post-meta\">'+escapeHtml(entry.published&&entry.published.$t)+'</div></header><div class=\"post-body\">'+safeBody(entry.content&&entry.content.$t)+'</div><footer class=\"post-footer\"><a href=\"'+escapeHtml(url)+'\">Open event details</a></footer>';
      main.appendChild(article);
    });
  }
  function loadPublishedFixtures(){
    var feedPath='/feeds/posts/default?alt=json'+'&'+'max-results=20';
    fetch(feedPath,{credentials:'same-origin'}).then(function(response){if(!response.ok){throw new Error('Feed request failed');}return response.json();}).then(function(payload){renderFeed((payload.feed&&payload.feed.entry)||[]);}).catch(function(){/* Native Blogger rendering remains the fallback. */});
  }
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',loadPublishedFixtures);}else{loadPublishedFixtures();}
  function updateCricketDate(){
    var target=document.getElementById('cricket-live-date-value');
    if(!target){return;}
    var parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Dhaka',weekday:'long',month:'long',day:'numeric',year:'numeric'}).formatToParts(new Date());
    var output='';
    parts.forEach(function(part){if(part.type!=='literal'){output+=part.value;}else{output+=part.value;}});
    target.textContent=output;
  }
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',updateCricketDate);}else{updateCricketDate();}
  window.setInterval(updateCricketDate,60000);
})();
